select TRD_PRODUCT_DEAL.TRADE_ID tradeId, '${effective}' effectStatus, fp1.FINPROD_NAME chlFinprodId, TRD_PRODUCT_DEAL_ADD.ENTRUST_ID entrustId, PTL_PORTFOLIO.PORTFOLIO_ID portfolioId, PTL_PORTFOLIO.PORTFOLIO_NAME portfolioName, TRD_PRODUCT_DEAL.FINPROD_TYPE2 finprodType, TRD_PRODUCT_DEAL.UNIT_CPRICE fCprice, TRD_PRODUCT_DEAL.YIELD * 100 fYield, TRD_PRODUCT_DEAL.FINPROD_ID finprodId, FIN_PRODUCT_TYPE.TYPE_6 assetOneType, FIN_TRADE_PRODUCT.TERM_TYPE termType, FIN_TRADE_PRODUCT.M_UNIT_CPRICE mCprice, FIN_TRADE_PRODUCT.M_YIELD * 100 mYield, FIN_TRADE_PRODUCT.M_TRADE_AMT mSettleAmt, TRD_PRODUCT_DEAL.TRADE_MARKET tradeMarket, PA_TRD_PRODUCT_DEAL.BACK_LEND_DIRECTION ps, TRD_PRODUCT_DEAL.PRIN_AMT prinAmt, TRD_PRODUCT_DEAL.CCY ccy, TRD_PRODUCT_DEAL.TRADE_DATE tradeDate, TRD_PRODUCT_DEAL.REMARK remark, FIN_DEAL_PLEDGE.PLEDGE_FINPROD_ID finpprodId, FIN_PRODUCT.FINPROD_NAME finprodNAME, FIN_PRODUCT.FINPROD_ABBR finprodAbbr, FIN_PRODUCT.FINPROD_MARKET_ID finprodIdShow, NULL workflowId, NULL workflowStatus from TRD_PRODUCT_DEAL left join TRD_PRODUCT_DEAL_ADD on TRD_PRODUCT_DEAL.TRADE_ID = TRD_PRODUCT_DEAL_ADD.TRADE_ID left join PA_TRD_PRODUCT_DEAL on TRD_PRODUCT_DEAL.TRADE_ID = PA_TRD_PRODUCT_DEAL.TRADE_ID left join PTL_TRADE on TRD_PRODUCT_DEAL.TRADE_ID = PTL_TRADE.BUSI_ID left join PTL_PORTFOLIO on PTL_PORTFOLIO.PORTFOLIO_ID = PTL_TRADE.PORTFOLIO_ID left join FIN_PRODUCT_TYPE on TRD_PRODUCT_DEAL.FINPROD_ID = FIN_PRODUCT_TYPE.FINPROD_ID left join FIN_TRADE_PRODUCT on TRD_PRODUCT_DEAL.TRADE_ID = FIN_TRADE_PRODUCT.FINPROD_ID left join FIN_DEAL_PLEDGE on TRD_PRODUCT_DEAL.TRADE_ID = FIN_DEAL_PLEDGE.FINPROD_ID left join FIN_PRODUCT on FIN_DEAL_PLEDGE.PLEDGE_FINPROD_ID = FIN_PRODUCT.FINPROD_ID LEFT JOIN FIN_PRODUCT fp1 on fp1.FINPROD_ID = TRD_PRODUCT_DEAL.CHL_ID LEFT JOIN FIN_DEAL_PLEDGE ON TRD_PRODUCT_DEAL.TRADE_ID = FIN_DEAL_PLEDGE.finprod_id where PTL_PORTFOLIO.INVEST_YESORNO='Y' and TRD_PRODUCT_DEAL.FINPROD_TYPE2 IN (#{bugOutTypeForword}, #{bugOutTypeNegative}) and TRD_PRODUCT_DEAL.PS = #{psPay} and TRD_PRODUCT_DEAL.TRADE_STATUS = #{tradeStatusInit} and TRD_PRODUCT_DEAL.IS_CANCEL = #{noFlag}
and (PTL_PORTFOLIO.PORTFOLIO_ID in
#{item}
or PTL_PORTFOLIO.PARENT_PORTFOLIO_ID in
#{item} )
AND (TRD_PRODUCT_DEAL.CHL_ID IN
null) OR TRD_PRODUCT_DEAL.CHL_ID in (
#{item}
)
AND (FIN_DEAL_PLEDGE.PLEDGE_FINPROD_ID IN
null) OR FIN_DEAL_PLEDGE.PLEDGE_FINPROD_ID in (
#{item}
)
and (PTL_PORTFOLIO.PORTFOLIO_ID IN (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}) or PTL_PORTFOLIO.PARENT_PORTFOLIO_ID IN (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}))
and TRD_PRODUCT_DEAL_ADD.ENTRUST_ID = #{entrustId}
and PA_TRD_PRODUCT_DEAL.BACK_LEND_DIRECTION = #{ps}
and TRD_PRODUCT_DEAL.TRADE_DATE >= to_date(#{dealDateStart}, 'yyyy-MM-dd')
and TRD_PRODUCT_DEAL.TRADE_DATE <= to_date(#{dealDateEnd}, 'yyyy-MM-dd')
group by TRD_PRODUCT_DEAL.TRADE_ID , TRD_PRODUCT_DEAL_ADD.ENTRUST_ID , PTL_PORTFOLIO.PORTFOLIO_ID , PTL_PORTFOLIO.PORTFOLIO_NAME , TRD_PRODUCT_DEAL.FINPROD_TYPE2 , TRD_PRODUCT_DEAL.UNIT_CPRICE , TRD_PRODUCT_DEAL.YIELD, TRD_PRODUCT_DEAL.FINPROD_ID , FIN_PRODUCT_TYPE.TYPE_6 , FIN_TRADE_PRODUCT.TERM_TYPE , FIN_TRADE_PRODUCT.M_UNIT_CPRICE , FIN_TRADE_PRODUCT.M_YIELD , FIN_TRADE_PRODUCT.M_TRADE_AMT , TRD_PRODUCT_DEAL.TRADE_MARKET , PA_TRD_PRODUCT_DEAL.BACK_LEND_DIRECTION , TRD_PRODUCT_DEAL.PRIN_AMT, TRD_PRODUCT_DEAL.CCY , TRD_PRODUCT_DEAL.TRADE_DATE , TRD_PRODUCT_DEAL.REMARK , FIN_DEAL_PLEDGE.PLEDGE_FINPROD_ID , FIN_PRODUCT.FINPROD_NAME , FIN_PRODUCT.FINPROD_ABBR, fp1.FINPROD_NAME, FIN_PRODUCT.FINPROD_MARKET_ID

