AND (FIN_DEAL_PLEDGE.PLEDGE_FINPROD_ID IN
null) OR FIN_DEAL_PLEDGE.PLEDGE_FINPROD_ID in (
#{item}
)
and TRD_PRODUCT_DEAL_ADD.ENTRUST_ID = #{entrustId}
and PA_TRD_PRODUCT_DEAL.BACK_LEND_DIRECTION = #{ps}
and TRD_PRODUCT_DEAL.TRADE_DATE >= to_date(#{dealDateStart}, 'yyyy-MM-dd')
and TRD_PRODUCT_DEAL.TRADE_DATE <= to_date(#{dealDateEnd}, 'yyyy-MM-dd')

select WFL_TRD_PRODUCT_DEAL.TRADE_ID tradeId, '${inflow}' effectStatus, fp1.FINPROD_NAME chlFinprodId, WFL_TRD_PRODUCT_DEAL_ADD.ENTRUST_ID entrustId, PTL_PORTFOLIO.PORTFOLIO_ID portfolioId, PTL_PORTFOLIO.PORTFOLIO_NAME portfolioName, WFL_TRD_PRODUCT_DEAL.FINPROD_TYPE2 finprodType, TRD_PRODUCT_DEAL.UNIT_CPRICE fCprice, TRD_PRODUCT_DEAL.YIELD * 100 fYield, WFL_TRD_PRODUCT_DEAL.FINPROD_ID finprodId, FIN_PRODUCT_TYPE.TYPE_6 assetOneType, FIN_TRADE_PRODUCT.TERM_TYPE termType, FIN_TRADE_PRODUCT.M_UNIT_CPRICE mCprice, FIN_TRADE_PRODUCT.M_YIELD * 100 mYield, FIN_TRADE_PRODUCT.M_TRADE_AMT mSettleAmt, WFL_TRD_PRODUCT_DEAL.TRADE_MARKET tradeMarket, WFL_PA_TRD_PRODUCT_DEAL.BACK_LEND_DIRECTION ps, WFL_TRD_PRODUCT_DEAL.PRIN_AMT prinAmt, WFL_TRD_PRODUCT_DEAL.CCY ccy, WFL_TRD_PRODUCT_DEAL.TRADE_DATE tradeDate, WFL_TRD_PRODUCT_DEAL.REMARK remark, FIN_DEAL_PLEDGE.PLEDGE_FINPROD_ID finpprodId, FIN_PRODUCT.FINPROD_NAME finprodNAME, FIN_PRODUCT.FINPROD_ABBR finprodAbbr, FIN_PRODUCT.FINPROD_MARKET_ID finprodIdShow, WFL_TRD_PRODUCT_DEAL.WORKFLOW_ID workflowId, WFL_TRD_PRODUCT_DEAL.WORKFLOW_STATUS workflowStatus from WFL_TRD_PRODUCT_DEAL left join WFL_TRD_PRODUCT_DEAL_ADD on WFL_TRD_PRODUCT_DEAL.TRADE_ID = WFL_TRD_PRODUCT_DEAL_ADD.TRADE_ID left join WFL_PA_TRD_PRODUCT_DEAL on WFL_TRD_PRODUCT_DEAL.TRADE_ID = WFL_PA_TRD_PRODUCT_DEAL.TRADE_ID left join PTL_PORTFOLIO on PTL_PORTFOLIO.PORTFOLIO_ID = WFL_TRD_PRODUCT_DEAL_ADD.PORTFOLIO_ID left join FIN_PRODUCT_TYPE on WFL_TRD_PRODUCT_DEAL.FINPROD_ID = FIN_PRODUCT_TYPE.FINPROD_ID left join FIN_TRADE_PRODUCT on WFL_TRD_PRODUCT_DEAL.TRADE_ID = FIN_TRADE_PRODUCT.FINPROD_ID left join TRD_PRODUCT_DEAL on WFL_TRD_PRODUCT_DEAL.TRADE_ID = TRD_PRODUCT_DEAL.TRADE_ID left join FIN_DEAL_PLEDGE on WFL_TRD_PRODUCT_DEAL.TRADE_ID = FIN_DEAL_PLEDGE.FINPROD_ID left join FIN_PRODUCT on FIN_DEAL_PLEDGE.PLEDGE_FINPROD_ID = FIN_PRODUCT.FINPROD_ID LEFT JOIN FIN_PRODUCT fp1 on fp1.FINPROD_ID = WFL_TRD_PRODUCT_DEAL.CHL_ID LEFT JOIN FIN_DEAL_PLEDGE ON WFL_TRD_PRODUCT_DEAL.TRADE_ID = FIN_DEAL_PLEDGE.finprod_id where PTL_PORTFOLIO.INVEST_YESORNO='Y' and WFL_TRD_PRODUCT_DEAL.FINPROD_TYPE2 IN (#{bugOutTypeForword}, #{bugOutTypeNegative}) and WFL_TRD_PRODUCT_DEAL.PS = #{psPay} and WFL_TRD_PRODUCT_DEAL.TRADE_STATUS = #{tradeStatusInit} and WFL_TRD_PRODUCT_DEAL.IS_CANCEL = #{noFlag}
