mapper.select:
        SELECT
            FINPROD_ID id,
            FINPROD_MARKET_ID || ':' || FINPROD_ABBR text,
            FINPROD_ABBR object
        FROM FIN_PRODUCT


                (
                    FINPROD_MARKET_ID LIKE CONCAT('%', CONCAT(#{search}, '%'))
                    OR
                    FINPROD_NAME LIKE CONCAT('%', CONCAT(#{search}, '%'))
                )


	   			and FINPROD_ID = #{initValue}


                AND FINPROD_TYPE2 = #{FINPROD_TYPE_TG}


                AND PROFIT_TYPE = #{PROFIT_TYPE}


				AND TRADE_MARKET = #{tradeMarket}

select TRD_PRODUCT_DEAL_ADD.ENTRUST_ID entrustId, PP.PORTFOLIO_ID portfolioId, TRD_PRODUCT_DEAL.F_TRADE_ID dealBussId, TRD_PRODUCT_DEAL.TRADE_DATE tradeDate, TRD_PRODUCT_DEAL.TRADE_MARKET tradeMarket, PA_TRD_PRODUCT_DEAL.BACK_LEND_DIRECTION ps, FIN_DEAL_PLEDGE.PLEDGE_FINPROD_ID finprodId, DECODE(TRD_PRODUCT_DEAL.SETTLE_SPEED, 0, '01', '02') settleSpeed, FIN_TRADE_PRODUCT.TERM_TYPE termType, FIN_TRADE_PRODUCT.TERM repoterm, FIN_TRADE_PRODUCT.BASIS basis, TRD_PRODUCT_DEAL.VDATE vdate, TRD_PRODUCT_DEAL.MDATE mdate, (TRD_PRODUCT_DEAL.MDATE - TRD_PRODUCT_DEAL.VDATE) actAmtDays, FIN_TRADE_PRODUCT.CALENDAR_ID dealCalId, TRD_PRODUCT_DEAL.SEC_MANAGE_ACCT_ID secAcctId, TRD_PRODUCT_DEAL.CCY ccy, TRD_PRODUCT_DEAL.CHL_ID chlId, TRD_PRODUCT_DEAL.FEE_AMT channelFee,
FIN_DEAL_PLEDGE.PLEDGE_NUMBER * 100 secTotalPrin, FIN_TRADE_PRODUCT.INT_RATE * 100 repoRate, TRD_PRODUCT_DEAL.UNIT_CPRICE fCprice,
TRD_PRODUCT_DEAL.UNIT_INT fIntAmt, TRD_PRODUCT_DEAL.UNIT_FPRICE fFprice, TRD_PRODUCT_DEAL.YIELD * 100 fYield, TRD_PRODUCT_DEAL.FPRICE_AMT fSettleAmt, TRD_PRODUCT_DEAL.TRADE_AMT tradeAmtAndFee, TRD_PRODUCT_DEAL.DELIVERY_TYPE fSettleMethod, FIN_TRADE_PRODUCT.M_UNIT_CPRICE mCprice, FIN_TRADE_PRODUCT.M_UNIT_INT mIntAmt, FIN_TRADE_PRODUCT.M_UNIT_FPRICE mFprice, FIN_TRADE_PRODUCT.M_YIELD * 100 mYield, FIN_TRADE_PRODUCT.M_TRADE_AMT mSettleAmt, FIN_TRADE_PRODUCT.M_DELIVERY_TYPE mSettleMethod, TRD_PRODUCT_DEAL.REMARK remark from TRD_PRODUCT_DEAL left join TRD_PRODUCT_DEAL_ADD on TRD_PRODUCT_DEAL.TRADE_ID = TRD_PRODUCT_DEAL_ADD.TRADE_ID left join PA_TRD_PRODUCT_DEAL on TRD_PRODUCT_DEAL.TRADE_ID = PA_TRD_PRODUCT_DEAL.TRADE_ID left join FIN_DEAL_PLEDGE on TRD_PRODUCT_DEAL.TRADE_ID = FIN_DEAL_PLEDGE.FINPROD_ID left join FIN_TRADE_PRODUCT on TRD_PRODUCT_DEAL.TRADE_ID = FIN_TRADE_PRODUCT.FINPROD_ID LEFT JOIN PTL_TRADE PT ON TRD_PRODUCT_DEAL.TRADE_ID = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO PP ON PT.PORTFOLIO_ID = PP.PORTFOLIO_ID where PP.INVEST_YESORNO = 'Y' AND TRD_PRODUCT_DEAL.TRADE_ID = #{tradeId}

mapper.update:
update PTL_SEC_POSITION
set AMOUNT = AMOUNT - #{amount,jdbcType=DECIMAL}
where PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
  and SEC_ACCT_ID = #{secAcctId,jdbcType=VARCHAR}
  and FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
  and BRANCH = #{branch,jdbcType=DECIMAL}
  and INV_AIM = #{invAim,jdbcType=VARCHAR}
  and HODING_TYPE = #{hodingType,jdbcType=VARCHAR}
  and CDATE = #{cdate,jdbcType=DATE}

mapper.select:
		 SELECT T.FIRST_UNIT_CPRICE fCprice, T.FIRST_UNIT_CPRICE2 fCprice2, T.ENTRUST_ID
   FROM ETR_ENTRUST_ADD T
  WHERE T.ENTRUST_ID = #{entrustId}

mapper.delete:
DELETE FROM
PTL_SEC_POSITION_FLOW
WHERE
PORTFOLIO_ID = #{portfolioId}

	AND SEC_ACCT_ID = #{secAcctId}


	AND FINPROD_ID = #{finprodId}


	AND CDATE = TO_DATE(#{substitutionDate}, 'yyyy-MM-dd')


	AND HODING_TYPE = #{hodingType}
